def skill():
    P = Rational(96 + 12, 2)      # int x f : 두 식을 더해 2로 나눈다
    Q = Rational(96 - 12, 2)      # int f   : 두 식을 빼서 2로 나눈다
    x = Symbol('x')
    a = P/(2*integrate(x**2, (x, 0, 3)))          # x f 의 짝수차 항 a x^2
    b = (Q - 2*integrate(x**2, (x, 0, 3)))/6      # f 의 짝수차 항 x^2 + b
    return (x**2 + a*x + b).subs(x, 2)

def standard():
    x, a, b = symbols('x a b')
    f = x**2 + a*x + b
    s = solve([integrate((x + 1)*f, (x, -3, 3)) - 96, integrate((x - 1)*f, (x, -3, 3)) - 12], [a, b])
    return f.subs(s).subs(x, 2)

def unique():
    x, a, b = symbols('x a b')
    f = x**2 + a*x + b
    s = solve([integrate((x + 1)*f, (x, -3, 3)) - 96, integrate((x - 1)*f, (x, -3, 3)) - 12], [a, b], dict=True)
    return sorted({f.subs(d).subs(x, 2) for d in s})
